package com.bankhighlighter;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bankHighlighter")
public interface BankHighlighterConfig extends Config
{
    @Alpha
    @ConfigItem(
        keyName = "highlightColor",
        position = 0,
        name = "Highlight colour",
        description = "Colour used to highlight bank clickboxes"
    )
    default Color highlightColor()
    {
        return new Color(0, 200, 255, 180);
    }

    @ConfigItem(
        keyName = "highlightDepositBoxes",
        position = 1,
        name = "Highlight deposit boxes",
        description = "Also highlight bank deposit boxes and other deposit-only bank fixtures"
    )
    default boolean highlightDepositBoxes()
    {
        return false;
    }

    @ConfigItem(
        keyName = "highlightGroupStorage",
        position = 2,
        name = "Highlight Group storage",
        description = "Also highlight dedicated Group Ironman storage chests"
    )
    default boolean highlightGroupStorage()
    {
        return false;
    }
}

package com.bankhighlighter;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class BankHighlighterOverlay extends Overlay
{
    private static final Stroke OUTLINE = new BasicStroke(2);
    private final BankHighlighterPlugin plugin;
    private final BankHighlighterConfig config;
    private final Client client;

    BankHighlighterOverlay(BankHighlighterPlugin plugin, BankHighlighterConfig config, Client client)
    {
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return null;
        }

        Map<TileObject, ObjectComposition> bankObjects = plugin.getBankObjects();
        if (bankObjects.isEmpty())
        {
            return null;
        }

        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null)
        {
            return null;
        }

        Color color = config.highlightColor();
        Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha() / 4);
        boolean highlightDepositBoxes = config.highlightDepositBoxes();
        boolean highlightGroupStorage = config.highlightGroupStorage();
        Color oldColor = graphics.getColor();
        Stroke oldStroke = graphics.getStroke();
        graphics.setStroke(OUTLINE);
        for (Map.Entry<TileObject, ObjectComposition> entry : bankObjects.entrySet())
        {
            TileObject object = entry.getKey();
            if (object.getWorldView() != worldView || object.getPlane() != worldView.getPlane())
            {
                continue;
            }
            BankTargetType type = plugin.getActiveTargetType(entry.getValue());
            if (type == BankTargetType.NONE
                || (type == BankTargetType.DEPOSIT_BOX && !highlightDepositBoxes)
                || (type == BankTargetType.GROUP_STORAGE && !highlightGroupStorage))
            {
                continue;
            }
            Shape clickbox = object.getClickbox();
            if (clickbox != null)
            {
                graphics.setColor(fill);
                graphics.fill(clickbox);
                graphics.setColor(color);
                graphics.draw(clickbox);
            }
        }
        graphics.setStroke(oldStroke);
        graphics.setColor(oldColor);
        return null;
    }
}

package com.bankhighlighter;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Bank Clickbox Highlighter",
    description = "Highlights bank clickboxes, with options for deposit boxes and Group storage",
    tags = {"bank", "booth", "chest", "highlight"}
)
public class BankHighlighterPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private OverlayManager overlayManager;
    @Inject private BankHighlighterConfig config;

    // A large object can occupy several tiles, so track the object instance only once.
    private final Map<TileObject, ObjectComposition> bankObjects = new IdentityHashMap<>();
    private final Map<Integer, ObjectComposition> definitions = new HashMap<>();
    private final Map<Integer, BankTargetType> targetDefinitions = new HashMap<>();
    private final Map<Integer, Boolean> bankCandidates = new HashMap<>();
    private volatile BankHighlighterOverlay overlay;
    private volatile boolean scanPending;

    @Provides
    BankHighlighterConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BankHighlighterConfig.class);
    }

    @Override
    protected void startUp()
    {
        BankHighlighterOverlay activeOverlay = new BankHighlighterOverlay(this, config, client);
        overlay = activeOverlay;
        overlayManager.add(activeOverlay);
        clientThread.invokeLater(() ->
        {
            if (overlay == activeOverlay)
            {
                scanPending = true;
            }
        });
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        overlay = null;
        scanPending = false;
        clearScene();
    }

    Map<TileObject, ObjectComposition> getBankObjects()
    {
        return bankObjects;
    }

    // getOpOverride walks the client's pending-spawn deque and is unsafe in spawn callbacks.
    // Classify from the object definition instead.
    BankTargetType getActiveTargetType(ObjectComposition definition)
    {
        if (definition.getImpostorIds() != null)
        {
            definition = definition.getImpostor();
        }
        return definition == null ? BankTargetType.NONE : classifyDefinition(definition);
    }

    private BankTargetType classifyDefinition(ObjectComposition definition)
    {
        return targetDefinitions.computeIfAbsent(definition.getId(),
            id -> classify(definition.getName(), definition.getActions()));
    }

    static BankTargetType classify(String name, String[] actions)
    {
        if (actions == null)
        {
            return BankTargetType.NONE;
        }

        boolean bankAction = false;
        boolean depositAction = false;
        boolean useAction = false;
        boolean openAction = false;
        for (String action : actions)
        {
            if ("Bank".equalsIgnoreCase(action))
            {
                bankAction = true;
            }
            else if ("Deposit".equalsIgnoreCase(action))
            {
                depositAction = true;
            }
            else if ("Use".equalsIgnoreCase(action))
            {
                useAction = true;
            }
            else if ("Open".equalsIgnoreCase(action))
            {
                openAction = true;
            }
        }

        String lowerName = name == null ? "" : name.toLowerCase(Locale.ROOT);
        boolean depositBox = lowerName.equals("deposit box") || lowerName.endsWith(" deposit box");
        boolean namedBank = lowerName.equals("bank") || lowerName.startsWith("bank ")
            || lowerName.endsWith(" bank");
        if (depositBox && (bankAction || depositAction || useAction))
        {
            return BankTargetType.DEPOSIT_BOX;
        }
        if (bankAction || (namedBank && useAction))
        {
            return BankTargetType.BANK;
        }
        if (namedBank && depositAction)
        {
            return BankTargetType.DEPOSIT_BOX;
        }
        if (lowerName.equals("group storage") && openAction)
        {
            return BankTargetType.GROUP_STORAGE;
        }
        return BankTargetType.NONE;
    }

    private boolean isBankCandidate(ObjectComposition definition)
    {
        if (classifyDefinition(definition) != BankTargetType.NONE)
        {
            return true;
        }
        int[] impostorIds = definition.getImpostorIds();
        if (impostorIds != null)
        {
            for (int id : impostorIds)
            {
                if (id >= 0)
                {
                    ObjectComposition impostor = client.getObjectDefinition(id);
                    if (impostor != null && classifyDefinition(impostor) != BankTargetType.NONE)
                    {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private void track(TileObject object)
    {
        if (object == null)
        {
            return;
        }

        int id = object.getId();
        ObjectComposition definition = definitions.computeIfAbsent(id, client::getObjectDefinition);
        if (definition != null && bankCandidates.computeIfAbsent(id,
            ignored -> isBankCandidate(definition)))
        {
            bankObjects.put(object, definition);
        }
    }

    private void trackSpawned(TileObject object)
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            scanPending = true;
            return;
        }
        track(object);
    }

    private void scanTile(Tile tile)
    {
        if (tile == null)
        {
            return;
        }
        GameObject[] gameObjects = tile.getGameObjects();
        if (gameObjects != null)
        {
            for (GameObject object : gameObjects)
            {
                track(object);
            }
        }
        track(tile.getWallObject());
    }

    private void clearScene()
    {
        bankObjects.clear();
        definitions.clear();
        targetDefinitions.clear();
        bankCandidates.clear();
    }

    private void scanScene()
    {
        bankObjects.clear();
        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null || worldView.getScene() == null)
        {
            return;
        }
        Tile[][][] tiles = worldView.getScene().getTiles();
        if (tiles == null)
        {
            return;
        }
        for (Tile[][] plane : tiles)
        {
            if (plane == null)
            {
                continue;
            }
            for (Tile[] column : plane)
            {
                if (column == null)
                {
                    continue;
                }
                for (Tile tile : column)
                {
                    scanTile(tile);
                    if (tile != null)
                    {
                        scanTile(tile.getBridge());
                    }
                }
            }
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            scanPending = true;
        }
        else
        {
            scanPending = false;
            clearScene();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (scanPending && client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null)
        {
            scanPending = false;
            scanScene();
        }
    }

    @Subscribe public void onGameObjectSpawned(GameObjectSpawned event) { trackSpawned(event.getGameObject()); }
    @Subscribe public void onGameObjectDespawned(GameObjectDespawned event) { bankObjects.remove(event.getGameObject()); }
    @Subscribe public void onWallObjectSpawned(WallObjectSpawned event) { trackSpawned(event.getWallObject()); }
    @Subscribe public void onWallObjectDespawned(WallObjectDespawned event) { bankObjects.remove(event.getWallObject()); }
}

package com.bankhighlighter;

enum BankTargetType
{
    NONE,
    BANK,
    DEPOSIT_BOX,
    GROUP_STORAGE
}

package com.bankhighlighter;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class BankHighlighterDetectionTest
{
    @Test
    public void detectsBanksByActionEvenWhenTheNameIsDifferent()
    {
        assertEquals(BankTargetType.BANK,
            BankHighlighterPlugin.classify("Chest", new String[] {"Open", "Bank"}));
        assertEquals(BankTargetType.BANK,
            BankHighlighterPlugin.classify("<col=ffff00>Bank Crab</col>", new String[] {"Bank", "Collect"}));
    }

    @Test
    public void detectsNamedBankFixturesWithDifferentActions()
    {
        assertEquals(BankTargetType.BANK,
            BankHighlighterPlugin.classify("Bank chest", new String[] {"Use"}));
        assertEquals(BankTargetType.BANK,
            BankHighlighterPlugin.classify("Bank chest", new String[] {"Use", "Collect"}));
    }

    @Test
    public void keepsDepositBoxesSeparate()
    {
        assertEquals(BankTargetType.DEPOSIT_BOX,
            BankHighlighterPlugin.classify("Bank deposit box", new String[] {"Deposit"}));
        assertEquals(BankTargetType.DEPOSIT_BOX,
            BankHighlighterPlugin.classify("Deposit box", new String[] {"Deposit"}));
        assertEquals(BankTargetType.DEPOSIT_BOX,
            BankHighlighterPlugin.classify("Bank deposit box", new String[] {"Bank", "Deposit"}));
    }

    @Test
    public void keepsGroupStorageSeparate()
    {
        assertEquals(BankTargetType.GROUP_STORAGE,
            BankHighlighterPlugin.classify("Group storage", new String[] {"Open"}));
        assertEquals(BankTargetType.NONE,
            BankHighlighterPlugin.classify("Group storage", new String[] {"Use"}));
    }

    @Test
    public void ignoresUnrelatedObjects()
    {
        assertEquals(BankTargetType.NONE,
            BankHighlighterPlugin.classify("Chest", new String[] {"Open"}));
        assertEquals(BankTargetType.NONE,
            BankHighlighterPlugin.classify("Bank chest", new String[] {"Open"}));
        assertEquals(BankTargetType.NONE,
            BankHighlighterPlugin.classify("Bank of Gielinor sign", new String[] {"Read"}));
        assertEquals(BankTargetType.NONE,
            BankHighlighterPlugin.classify("Ore hopper", new String[] {"Deposit"}));
        assertEquals(BankTargetType.NONE,
            BankHighlighterPlugin.classify("Bank chest", null));
    }
}

